// ============================================================================
// Finance Calc -- entry, input recovery, validation, quote
// ============================================================================
//
// -- EMI extension (31 Aug 2026) ---------------------------------------------
// This node could not compute an instalment at all. On 31 Aug a live customer
// asked "what would the monthly payment be over 60 months?" and the agent
// invented AED 11,200/month -- it had amortised the full AED 585,000, i.e.
// 100% financing, which no UAE bank offers. The true figure was ~7,800-9,200.
//
// Everything below the ORIGINAL banner is unchanged in behaviour; the EMI
// block is purely additive and every pre-existing output field keeps its name
// and its value. Rules applied:
//   * A 20% down-payment floor (80% LTV) is enforced. It was written here as
//     "CBUAE Regulation No. 29/2011"; that attribution is UNVERIFIED and is now
//     recorded as such in public.policy_rule, so the floor is enforced but is
//     no longer described to a customer as anyone's regulation. Banks
//     commercially cap USED cars at 70% LTV (30% down) and ALBA CARS sells used
//     cars, so 30% is what we ASSUME when the customer states nothing; a stated
//     20-30% is still quoted, but flagged as below what banks usually want.
//   * Maximum repayment period 60 months. Hard cap, never exceeded. Same
//     UNVERIFIED regulatory status as the floor above.
//   * Reducing-balance amortisation: P * r / (1 - (1+r)^-n), r = apr/100/12.
//     The BANDS APRs are already reducing-balance, so they feed this directly.
//   * Positive trade-in equity is real money and counts toward the down
//     payment; negative equity is NOT rolled into the loan here.
//
// The whole body is wrapped in try/catch: this node's contract is that every
// failure is a RETURNED item, never a thrown execution.
// ============================================================================
try {

//
// -- Entry-path resolution ---------------------------------------------------
// Webhook Trigger -> Verify JWT -> here   (public HTTP; auth enforced)
// Called as Tool  -> here                 (sub-workflow; already trusted)
//
// $('Webhook Trigger') THROWS when that node did not run in this execution --
// it does NOT return undefined, so `?.` and `||` cannot rescue it, and an
// Expression field cannot hold try/catch. That is why this lives in a Code node.
let webhookJson = null;
try {
  webhookJson = $('Webhook Trigger').first().json;
} catch (e) {
  // tool / sub-workflow path -- Webhook Trigger never executed.
}

let src;
let viaWebhook = false;
if (webhookJson) {
  viaWebhook = true;
  // 'Verify JWT' runs with onError = continueRegularOutput, so a rejected
  // token arrives here as data instead of failing the execution.
  const auth = $input.first().json || {};
  if (!auth.id) {
    return [{ json: {
      status: 'error',
      errors: ['Unauthorized. A valid Supabase session token is required in the Authorization header.'],
      calculatedAt: new Date().toISOString()
    } }];
  }
  src = webhookJson.body || webhookJson;
} else {
  src = $input.first().json || {};
}

// -- Degraded-mode envelope recovery (30 Aug 2026) ---------------------------
// n8n decides how a toolWorkflow presents itself to the model from ONE thing:
// whether the CALLER node's persisted `workflowInputs.schema` array is
// non-empty (WorkflowToolService.ts: `useSchema = (schema ?? []).length > 0`).
// It never inspects the sub-workflow at runtime. If that array is empty the
// tool degrades to a LangChain DynamicTool -- a single free-text parameter --
// and every argument the model produced arrives as ONE JSON string.
//
// This node is the last line of defence for that case. On 30 Aug exec 6668 the
// agent called this tool ELEVEN times in 147s, cycling field names and quoting
// styles, trying to guess a contract it could not satisfy; the customer got a
// canned apology. Recover the arguments rather than reject them.
//
// The wrapper key differs by layer: n8n re-wraps as { query: ... }, while the
// LangChain tool-call argument is logged as { input: ... }. Accept both.
// Both keys must ALSO be declared on the Called as Tool trigger, because a
// schema-declared trigger hard-filters every undeclared key
// (ExecuteWorkflowTrigger: pickBy(json, key => declaredKeys.has(key))).
function asObject(v) {
  if (v === null || v === undefined) return {};
  if (typeof v === 'object') return v;
  if (typeof v === 'string') {
    const s = v.trim();
    if (!s) return {};
    if (s[0] === '{' || s[0] === '[') {
      try { const p = JSON.parse(s); return (p && typeof p === 'object') ? p : {}; } catch (e) { return {}; }
    }
    // Bare scalar, e.g. the model sent just "600". Only a lone number is
    // unambiguous enough to interpret, and only as the credit score --
    // it is the one argument this tool always needs.
    if (/^\d{3}$/.test(s)) return { creditScore: Number(s) };
    return {};
  }
  return {};
}

const envelope = Object.assign({}, asObject(src.input), asObject(src.query));
const degraded = Object.keys(envelope).length > 0;

// A schema-declared trigger pre-seeds every declared field with null, so a
// field the caller did not supply is null here, not undefined. Treat both as
// absent and fall back to the envelope.
function pick(key) {
  const direct = src[key];
  if (direct !== undefined && direct !== null && direct !== '') return direct;
  return envelope[key];
}

// -- Inputs ------------------------------------------------------------------
const MIN_VEHICLE_VALUE_AED = 5000;

const rawVehicleIn = pick('vehicleValue');
const rawPayoffIn  = pick('loanPayoffAmount');
const rawVehicle = (rawVehicleIn === undefined || rawVehicleIn === null || rawVehicleIn === '')
  ? NaN : parseFloat(rawVehicleIn);
const rawPayoff = (rawPayoffIn === undefined || rawPayoffIn === null || rawPayoffIn === '')
  ? NaN : parseFloat(rawPayoffIn);
// Credit score is entered manually from the customer's AECB report -- real-time
// bureau lookups need a licensed financial-institution agreement in the UAE.
const creditScore = parseInt(pick('creditScore'), 10);

// -- EMI inputs (additive, all optional) -------------------------------------
// DEFAULT DOWN PAYMENT -- single point of change, change it here and nowhere else.
const DEFAULT_DOWN_PAYMENT_PCT = 30; // used-car norm (70% LTV) assumed when the customer states nothing

// Two different numbers, deliberately kept apart:
//   MIN_DOWN_PAYMENT_PCT  -- the HARD floor this desk quotes within. A stated
//     down payment below it is refused outright. It has long been ANNOTATED as
//     CBUAE Regulation No. 29/2011, but that attribution has never been checked
//     against the instrument by anyone on this project: it is registered in
//     public.policy_rule as AE/FINANCE/MIN_DOWN_PAYMENT_PCT, DRAFT /
//     NOT_VERIFIED, source "A constant in this codebase -- NOT a central bank".
//     Enforce it; do not tell a customer whose rule it is.
//   DEFAULT_DOWN_PAYMENT_PCT -- what we ASSUME when the customer stated nothing.
//     UAE banks commercially cap USED cars at 70% LTV and ALBA CARS sells used
//     cars, so the assumption is 30%. A stated 20-30% is still quoted, but
//     flagged as below what a bank will usually want on a used car.
const MIN_DOWN_PAYMENT_PCT = 20;                           // desk floor, ENFORCED. Regulatory status UNVERIFIED -- policy_rule AE/FINANCE/MIN_DOWN_PAYMENT_PCT
const MAX_LTV_PCT       = 100 - MIN_DOWN_PAYMENT_PCT;      // 80% -- the floor enforced
const USED_CAR_LTV_PCT  = 100 - DEFAULT_DOWN_PAYMENT_PCT;  // 70% -- the commercial norm
const DEFAULT_TENURE_MONTHS = 60;
const MAX_TENURE_MONTHS = 60;   // desk cap, ENFORCED. Never exceed. Regulatory status
                                // UNVERIFIED -- policy_rule AE/FINANCE/MAX_TENURE_MONTHS.
                                // NOTE: this rule also exists in TWO places this workflow
                                // does not own -- a CHECK constraint on finance_quotes
                                // (finance_quotes_tenure_months_check) and the browser
                                // constant MAX_TENURE_MONTHS_CBUAE in
                                // apps/executive-dashboard/screens/finance.js. Three copies,
                                // one unverified figure.
const MIN_TENURE_MONTHS = 12;

function num(v) {
  if (v === undefined || v === null || v === '') return NaN;
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : NaN;
}

// vehiclePrice is the car being BOUGHT. vehicleValue (above) is the TRADE-IN.
// They are different numbers and conflating them is what produced the AED
// 11,200 figure, so they are kept strictly separate.
const rawVehiclePrice   = num(pick('vehiclePrice'));
const rawDownPayment    = num(pick('downPayment'));
const rawDownPaymentPct = num(pick('downPaymentPct'));
const rawTenureMonths   = num(pick('tenureMonths'));

// A customer with NO trade-in still deserves a rate. vehicleValue used to be
// unconditionally mandatory, so a cash-in-hand buyer asking "what rate do I
// get?" could never be answered -- the tool rejected the call and the agent
// asked for a trade-in value the customer did not have.
const hasTradeIn = Number.isFinite(rawVehicle) && rawVehicle >= MIN_VEHICLE_VALUE_AED;
const vehicleValue = hasTradeIn ? rawVehicle : 0;
const loanPayoffAmount = Number.isFinite(rawPayoff) && rawPayoff >= 0 ? rawPayoff : 0;

// Attribution. A finance figure carrying a lender disclaimer must be traceable
// to a customer. SECURITY: prefer the caller-injected value. The envelope is
// model-controlled, so it is only a fallback for degraded mode, and when it is
// used the quote is flagged so the Finance Desk can see the identity was not
// established by the workflow.
const callerEmail = (src.lead_email || '').toString().trim();
const envEmail = (envelope.lead_email || envelope.email || '').toString().trim();
const leadEmail = callerEmail || envEmail || null;
const emailFromModel = !callerEmail && !!envEmail;
const leadName = (src.lead_name || envelope.lead_name || envelope.name || null);
const quotedBy = (src.quoted_by || envelope.quoted_by || envelope.rep || null);

// -- Validation --------------------------------------------------------------
// Error payloads are written FOR A LANGUAGE MODEL, not for a log file. A bare
// list of complaints made the agent retry the same call eleven times. Every
// rejection now leads with an imperative instruction telling the agent exactly
// what to do next, and never to repeat the same call.
const problems = [];
if (Number.isFinite(rawVehicle) && rawVehicle > 0 && rawVehicle < MIN_VEHICLE_VALUE_AED) {
  problems.push('vehicleValue was ' + rawVehicle + ', which is too small to be a real vehicle. Omit vehicleValue entirely if the customer has no trade-in.');
}
if (Number.isFinite(rawPayoff) && rawPayoff < 0) {
  problems.push('loanPayoffAmount cannot be negative. Use 0 when there is no outstanding loan.');
}
if (!hasTradeIn && Number.isFinite(rawPayoff) && rawPayoff > 0) {
  problems.push('loanPayoffAmount was supplied without a vehicleValue. Send both, or neither.');
}
if (!Number.isFinite(creditScore) || creditScore < 300 || creditScore > 900) {
  problems.push('creditScore is missing or outside 300-900. It is the only argument this tool always needs.');
}
if (!leadEmail) {
  problems.push('lead_email did not reach this tool. This is a WORKFLOW WIRING FAULT, not something the customer can fix.');
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(leadEmail)) {
  problems.push('lead_email "' + leadEmail + '" is not a valid email address.');
}

if (problems.length) {
  const emailIsTheOnlyProblem = problems.length === 1 && problems[0].indexOf('WORKFLOW WIRING FAULT') !== -1;
  return [{ json: {
    status: 'input_error',
    // The model reads this first. Keep it imperative and unambiguous.
    instruction: emailIsTheOnlyProblem
      ? 'STOP. Do not call finance_calculator again in this turn -- retrying cannot fix this, the fault is in the workflow wiring and not in your arguments. Tell the customer, in their own language, that you are getting their indicative rate confirmed by a colleague and will come straight back with it. Do not mention tools, systems or errors, and do not ask them for an email address.'
      : 'Fix the arguments listed in `problems` and call finance_calculator exactly ONCE more. Never repeat a call with arguments you have already tried. If you cannot fix them from the conversation, stop calling tools and ask the customer, in plain language, for the single missing detail.',
    problems: problems,
    expected: {
      creditScore: 'number, 300-900, REQUIRED. The customer AECB score.',
      vehicleValue: 'number, AED, OPTIONAL. Trade-in market value. Omit if no trade-in.',
      loanPayoffAmount: 'number, AED, OPTIONAL. Outstanding loan on the trade-in. Omit if no trade-in.',
      lead_email: 'Supplied automatically by the workflow. NEVER ask the customer for it.'
    },
    example_valid_call: { creditScore: 720, vehicleValue: 85000, loanPayoffAmount: 20000 },
    example_valid_call_no_trade_in: { creditScore: 720 },
    lead_email: leadEmail,
    lead_name: leadName,
    _degraded: degraded,
    calculatedAt: new Date().toISOString()
  } }];
}

// -- Rate bands --------------------------------------------------------------
// Rewritten 30 Aug 2026. The previous table quoted a SINGLE point APR per band
// on US FICO cut-offs (720/680/620, "Prime Plus"/"Subprime"), and its weakest
// band quoted 12.5% -- above Emirates NBD's published ceiling of 9.00%
// reducing / 9.65% APR. Three things were wrong with that and all three
// mattered, because these numbers are read out to real customers on WhatsApp:
//
//   1. UAE banks advertise a FLAT rate; the true cost is the reducing-balance
//      rate, ~1.87x the flat rate over 60 months. An unlabelled number is read
//      as flat and therefore understates the cost by roughly half. This was
//      justified here by "CBUAE Consumer Protection Standard 2.3.1.13", which
//      is ITSELF an UNVERIFIED citation and is not registered in policy_rule.
//      It stays only as a comment: labelling the APR is the conservative
//      behaviour whether or not the standard says so, and no customer-facing
//      string repeats the citation. Do not promote it into one.
//   2. Band cut-offs now follow ADCB's published AECB bands -- the only band
//      set published by an actual UAE lender. AECB itself publishes none.
//   3. No single point rate is quoted. Every UAE lender publishes a range and
//      states the bank sets the final rate on approval; a dealer asserting one
//      exact figure is asserting something it does not control.
//
// Basis: used car, 60-month term, salary transfer. Ranges are anchored to the
// observed used-car market at the strong end and capped at Emirates NBD's
// published 9.00% reducing / 9.65% APR ceiling at the weak end.
// Without salary transfer, add roughly 1.4pp -- surfaced as a caveat.
const BANDS = [
  { min: 746, band: 'Excellent', aprLow: 5.3, aprHigh: 6.7,  flatLow: 2.50, flatHigh: 3.20 },
  { min: 711, band: 'Very good', aprLow: 5.9, aprHigh: 7.5,  flatLow: 2.75, flatHigh: 3.65 },
  { min: 651, band: 'Good',      aprLow: 6.7, aprHigh: 8.7,  flatLow: 3.20, flatHigh: 4.35 },
  { min: 541, band: 'Fair',      aprLow: 8.2, aprHigh: 9.65, flatLow: 4.05, flatHigh: 4.90 }
];
const hit = BANDS.find(b => creditScore >= b.min) || null;

// -- DISCLAIMER (rewritten 3 Sep 2026) ---------------------------------------
// This string is read out to customers on WhatsApp. It used to end
//   "Min 20% down payment, max 60 months (UAE Central Bank rules)."
// which put a REGULATOR'S NAME behind two numbers that came from constants
// typed into apps/executive-dashboard/screens/finance.js with no source, no
// effective date and no verifier. Both are registered in public.policy_rule as
// AE/FINANCE/MIN_DOWN_PAYMENT_PCT and AE/FINANCE/MAX_TENURE_MONTHS, both
// DRAFT / NOT_VERIFIED, and public.v_policy_authoritative returns ZERO rows --
// so there is nothing authoritative to quote. policy_citation() for either of
// them does not return a hedge, it RAISES: "There is no verified source ... so
// no regulatory claim may be made about it. Get one, or say nothing."
//
// So we say nothing about any regulator. What is left is not a claim about UAE
// law or about any bank's credit policy -- it is a statement about THIS QUOTE:
// these are the limits the calculator computed within, provable from the code
// and from the finance_quotes row this run writes. That is the only version of
// the sentence the dealership can defend to a customer who asks.
//
// The percentages are interpolated from the enforced constants rather than
// retyped, so the sentence cannot drift away from the arithmetic it describes.
//
// WHEN A RULE IS VERIFIED: do not hard-code the regulation here. Read
// public.policy_citation('AE','FINANCE','<rule>') and append what it returns.
// A literal is what caused this defect.
const DISCLAIMER = 'Indicative only, not a bank approval. The bank sets the final rate after reviewing the AECB report, salary transfer and employer. Shown as reducing-balance APR including fees. Quoted on a minimum '
  + MIN_DOWN_PAYMENT_PCT + '% down payment over at most ' + MAX_TENURE_MONTHS
  + ' months: those are the limits this desk quotes within, not a statement of law or of any bank policy. The bank sets its own terms on approval.';

// Below 541 no rate is quoted at all. Every rate this dealership could honestly
// offer sits inside a published band, and there is no published UAE band for a
// file this weak -- so the honest answer is a referral, not a worse number.
if (!hit) {
  return [{ json: {
    status: 'success',
    quotable: false,
    credit_score: creditScore,
    credit_band: 'Poor (below 541 on the AECB scale)',
    instruction: 'Do NOT quote any rate or percentage for this customer. Tell them warmly that with this credit profile the rate has to come from the bank directly rather than from an indicative table, and that a colleague will walk them through the options -- including a larger down payment, which improves approval. Do not read this instruction out and do not mention scores unless they raise it.',
    disclaimer: DISCLAIMER,
    has_trade_in: hasTradeIn,
    equity_aed: hasTradeIn ? Math.round(vehicleValue - loanPayoffAmount) : null,
    lead_email: leadEmail, lead_name: leadName, quoted_by: quotedBy,
    email_from_model: emailFromModel, _degraded: degraded,
    calculated_at: new Date().toISOString()
  } }];
}

const equity = vehicleValue - loanPayoffAmount;
const ltv = vehicleValue > 0 ? Math.round((loanPayoffAmount / vehicleValue) * 1000) / 10 : null;

// -- EMI / instalment --------------------------------------------------------
// Reached ONLY on the quotable path: the `if (!hit)` Poor-band branch above has
// already returned, so a sub-541 file never gets an instalment. That is
// deliberate -- no rate, no payment.
function monthlyPayment(principal, aprPct, months) {
  if (!Number.isFinite(principal) || principal <= 0) return null;
  if (!Number.isFinite(months) || months <= 0) return null;
  if (!Number.isFinite(aprPct)) return null;
  const r = aprPct / 100 / 12;
  if (r === 0) return principal / months;              // no divide-by-zero path
  const denom = 1 - Math.pow(1 + r, -months);
  if (!Number.isFinite(denom) || denom === 0) return null;
  return principal * r / denom;
}

// Tenure: default 60, floored at 12, HARD-capped at 60 (desk cap; regulatory
// status unverified -- see MAX_TENURE_MONTHS above).
let tenureMonths = Number.isFinite(rawTenureMonths) && rawTenureMonths > 0
  ? Math.round(rawTenureMonths) : DEFAULT_TENURE_MONTHS;
const tenureCapped = tenureMonths > MAX_TENURE_MONTHS;
if (tenureMonths > MAX_TENURE_MONTHS) tenureMonths = MAX_TENURE_MONTHS;
if (tenureMonths < MIN_TENURE_MONTHS) tenureMonths = MIN_TENURE_MONTHS;

const hasVehiclePrice = Number.isFinite(rawVehiclePrice) && rawVehiclePrice >= MIN_VEHICLE_VALUE_AED;
const vehiclePrice = hasVehiclePrice ? rawVehiclePrice : null;

// Positive trade-in equity is cash toward the down payment. Negative equity is
// a debt to settle, NOT something this node rolls into the loan.
const equityApplied = (hasTradeIn && equity > 0)
  ? (hasVehiclePrice ? Math.min(equity, vehiclePrice) : equity) : 0;

let emiAvailable = false;
let emiReason = null;
let minDownPayment = null;
let downPaymentCash = null;
let downPaymentTotal = null;
let downPaymentPct = null;
let downPaymentAssumed = false;
let downPaymentShortfall = null;
let belowUsedCarNorm = false;
let normDownPayment = null;
let financed = null;
let monthlyLow = null, monthlyHigh = null;
let totalCreditLow = null, totalCreditHigh = null;
let monthlyRange = null;
let emiInstruction = null;

if (!hasVehiclePrice) {
  emiReason = 'No vehiclePrice was supplied, so no monthly payment can be calculated. '
    + 'Do NOT invent, estimate or guess a monthly figure. Ask the customer which vehicle '
    + '(or its price) and call finance_calculator once more with vehiclePrice.';
} else {
  minDownPayment  = Math.round(vehiclePrice * (MIN_DOWN_PAYMENT_PCT / 100));
  normDownPayment = Math.round(vehiclePrice * (DEFAULT_DOWN_PAYMENT_PCT / 100));

  // A stated down payment is CASH from the customer; trade-in equity is on top.
  let statedCash = NaN;
  if (Number.isFinite(rawDownPayment) && rawDownPayment >= 0) {
    statedCash = rawDownPayment;
  } else if (Number.isFinite(rawDownPaymentPct) && rawDownPaymentPct >= 0 && rawDownPaymentPct <= 100) {
    statedCash = vehiclePrice * (rawDownPaymentPct / 100);
  }

  if (Number.isFinite(statedCash)) {
    downPaymentCash = statedCash;
    downPaymentTotal = statedCash + equityApplied;
  } else {
    // Nothing stated -> apply the used-car norm, and say so. Trade-in equity
    // counts toward that floor rather than being added on top of it.
    downPaymentAssumed = true;
    downPaymentTotal = Math.max(normDownPayment, equityApplied);
    downPaymentCash = downPaymentTotal - equityApplied;
  }

  if (downPaymentTotal + 0.5 < minDownPayment) {
    // Never silently raise the customer's number. Name the gap instead.
    downPaymentShortfall = Math.round(minDownPayment - downPaymentTotal);
    // 3 Sep 2026: this text is relayed to the customer by the agent, so the
    // words "legal minimum" and "the UAE Central Bank caps" were a regulatory
    // claim resting on an unverified constant (policy_rule
    // AE/FINANCE/MIN_DOWN_PAYMENT_PCT, DRAFT / NOT_VERIFIED). The floor is
    // still enforced exactly as before -- it is just no longer attributed to
    // anyone who has not been checked.
    emiReason = 'The stated down payment of AED ' + Math.round(downPaymentTotal)
      + ' is below the minimum this desk quotes on, AED ' + minDownPayment + ' ('
      + MIN_DOWN_PAYMENT_PCT + '% of AED ' + Math.round(vehiclePrice)
      + '). Do NOT describe this minimum as a legal or regulatory requirement -- there is no verified source for that. '
      + 'Shortfall AED ' + downPaymentShortfall + '. Tell the customer that AED '
      + minDownPayment + ' is the minimum this quote can be built on -- do not quote a monthly payment and do '
      + 'not pretend the smaller amount works. On a used car most banks will actually want '
      + DEFAULT_DOWN_PAYMENT_PCT + '% (AED ' + normDownPayment + ').';
  } else if (vehiclePrice - downPaymentTotal <= 0) {
    financed = 0;
    emiReason = 'The down payment and trade-in equity cover the full price, so no '
      + 'finance is needed. Do not quote a monthly payment.';
  } else {
    financed = vehiclePrice - downPaymentTotal;
    belowUsedCarNorm = downPaymentTotal + 0.5 < normDownPayment;
    const pLow  = monthlyPayment(financed, hit.aprLow,  tenureMonths);
    const pHigh = monthlyPayment(financed, hit.aprHigh, tenureMonths);
    if (pLow === null || pHigh === null) {
      emiReason = 'The instalment could not be computed from the supplied figures. '
        + 'Do not invent a monthly payment.';
    } else {
      emiAvailable = true;
      monthlyLow  = Math.round(pLow);
      monthlyHigh = Math.round(pHigh);
      monthlyRange = monthlyLow + ' - ' + monthlyHigh;
      totalCreditLow  = Math.round(pLow  * tenureMonths - financed);
      totalCreditHigh = Math.round(pHigh * tenureMonths - financed);
      emiInstruction = 'Quote the monthly payment as a RANGE (AED ' + monthlyRange
        + ' over ' + tenureMonths + ' months), never a single figure, and always state the '
        + 'down payment you assumed. '
        + (downPaymentAssumed
            ? 'The customer did NOT state a down payment -- you assumed '
              + DEFAULT_DOWN_PAYMENT_PCT + '% (AED ' + Math.round(downPaymentTotal)
              + '). Say so explicitly.'
            : 'This uses the down payment the customer stated (AED '
              + Math.round(downPaymentTotal) + ').')
        + (equityApplied > 0
            ? ' AED ' + Math.round(equityApplied) + ' of that comes from their trade-in equity.'
            : '')
        + (belowUsedCarNorm
            ? ' WARNING: that is below the ' + DEFAULT_DOWN_PAYMENT_PCT + '% most UAE banks want on a '
              + 'USED car (' + USED_CAR_LTV_PCT + '% LTV). This desk will still quote down to '
              + MIN_DOWN_PAYMENT_PCT + '%, but the bank may require AED ' + normDownPayment
              + '. Say so, and do NOT tell the customer whether any regulator permits it -- we have no verified source for that.'
            : '')
        + ((hasTradeIn && equity < 0)
            ? ' Their trade-in is in negative equity (AED ' + Math.abs(Math.round(equity))
              + ' owing above its value); that must be settled separately and is NOT in this payment.'
            : '')
        + ' Never present it as a bank approval.';
    }
  }
  if (!emiAvailable && downPaymentTotal !== null) {
    downPaymentPct = Math.round((downPaymentTotal / vehiclePrice) * 1000) / 10;
  }
}
if (emiAvailable) {
  downPaymentPct = Math.round((downPaymentTotal / vehiclePrice) * 1000) / 10;
}

return [{
  json: {
    status: 'success',
    quotable: true,
    credit_score: creditScore,
    credit_band: hit.band,
    // Always a range, always labelled. Never emit a bare number downstream.
    indicative_apr_range_pct: hit.aprLow + ' - ' + hit.aprHigh,
    indicative_apr_low_pct: hit.aprLow,
    indicative_apr_high_pct: hit.aprHigh,
    rate_basis: 'reducing-balance APR, inclusive of fees',
    equivalent_flat_rate_range_pct: hit.flatLow + ' - ' + hit.flatHigh,
    assumes: 'used car, 60-month term, salary transfer to the lending bank',
    without_salary_transfer_note: 'Without salary transfer add roughly 1.4 percentage points.',
    instruction: 'Quote the RANGE, never a single figure, and always say it is reducing-balance APR. Include the disclaimer. Do not convert to a monthly payment unless the customer asks and you know the vehicle price and down payment. Never present the flat-rate equivalent on its own.',
    disclaimer: DISCLAIMER,
    has_trade_in: hasTradeIn,
    equity_aed: hasTradeIn ? Math.round(equity) : null,
    equity_status: hasTradeIn ? (equity >= 0 ? 'Positive' : 'Negative') : 'No trade-in',
    loan_to_value_pct: ltv,
    vehicle_value_aed: hasTradeIn ? Math.round(vehicleValue) : null,
    loan_payoff_aed: hasTradeIn ? Math.round(loanPayoffAmount) : null,
    lead_email: leadEmail,
    lead_name: leadName,
    quoted_by: quotedBy,
    email_from_model: emailFromModel,
    _degraded: degraded,
    _via_webhook: viaWebhook,

    // -- EMI block (additive, 31 Aug 2026). Nothing above this line changed. --
    emi_available: emiAvailable,
    emi_unavailable_reason: emiReason,
    emi_instruction: emiInstruction,
    vehicle_price_aed: hasVehiclePrice ? Math.round(vehiclePrice) : null,
    max_ltv_pct: MAX_LTV_PCT,
    min_down_payment_aed: minDownPayment,
    down_payment_aed: downPaymentTotal === null ? null : Math.round(downPaymentTotal),
    down_payment_cash_aed: downPaymentCash === null ? null : Math.round(downPaymentCash),
    down_payment_pct: downPaymentPct,
    down_payment_assumed: downPaymentAssumed,
    down_payment_shortfall_aed: downPaymentShortfall,
    down_payment_below_used_car_norm: belowUsedCarNorm,
    trade_in_equity_applied_aed: Math.round(equityApplied),
    financed_aed: financed === null ? null : Math.round(financed),
    tenure_months: tenureMonths,
    tenure_capped: tenureCapped,
    monthly_payment_low_aed: monthlyLow,
    monthly_payment_high_aed: monthlyHigh,
    monthly_payment_range_aed: monthlyRange,
    total_cost_of_credit_low_aed: totalCreditLow,
    total_cost_of_credit_high_aed: totalCreditHigh,

    calculated_at: new Date().toISOString()
  }
}];

} catch (err) {
  // The node's contract: every failure is a RETURNED item, never a thrown
  // execution. Anything unexpected -- malformed $input, a missing helper, a
  // numeric edge case -- lands here instead of failing the whole workflow.
  return [{ json: {
    status: 'error',
    errors: ['finance_calculator failed internally: ' + ((err && err.message) ? err.message : String(err))],
    instruction: 'STOP. Do not call finance_calculator again in this turn. Tell the customer, in their own language, that you are having their figures confirmed by a colleague and will come straight back. Do not mention tools or errors, and NEVER invent a rate or a monthly payment.',
    calculatedAt: new Date().toISOString()
  } }];
}

// Re-emit the calculation. 'Log Quote' returns an empty body
// (Prefer: return=minimal), so without this the webhook would answer with
// nothing. Also keeps the sub-workflow caller contract intact.
return $('Calculate Equity & Tier').all();

// Delivery Report - the last workflow still asserting a write it never checked.
//
// `Log Quote` swallows its own failure (onError: continueRegularOutput) and
// `Audit Log` decided SUCCESS purely from whether the MATHS succeeded, never
// from whether the `finance_quotes` row landed. So a dropped insert produced a
// green audit row and an empty Finance Desk.
//
// Two inbound paths meet here: the valid-quote path through `Log Quote`, and
// the rejected path straight from `Quote Valid?`. `$('Log Quote')` THROWS on
// the second one -- a rejection is not a drop, so it is not claimed there.
const calc = $('Calculate Equity & Tier').first().json;
const rejected = calc.status !== 'success';

const CLAIMED = rejected ? [] : [
  { node: 'Log Quote', what: 'finance_quotes row (the quote the Finance Desk reads)', critical: true },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 200) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);
const dropped = results.filter(r => !r.ok);
const critical = dropped.filter(r => r.critical);

// A rejection is a correct outcome, not a failure to deliver. It keeps its own
// status so the Finance Desk can still tell "we refused to quote" apart from
// "we quoted and lost it".
//
// -- 01 Sep 2026 - WHY THERE IS NO 'FAILED' RUNG ANY MORE ---------------------
// This node wrote FAILED whenever a dropped claim was tiered critical. 'Log
// Quote' is the ONLY claim and it was tiered critical, so the PARTIAL rung was
// unreachable and every lost finance_quotes row was filed as a failure. Five
// live rows read "Quote issued | 1 of 1 claimed steps did not land" under status
// FAILED. Read that sentence: the customer HAD the quote, only the record was
// lost. That is a partial delivery, and nexus_outcome_class() in Postgres has
// been carrying a correction rule to say so on this workflow's behalf. This
// change is what lets that rule be deleted.
//
// FAILED has exactly one owner: nexus_error_handler, the errorWorkflow set on
// this workflow, which writes it from an Error Trigger when an execution STOPS.
// This node only runs on an execution that did NOT stop, so it is structurally
// not entitled to claim the work could not complete. The worst it can honestly
// report is that some of the work did not land.
//
// `critical` is still computed and still reported - which claims matter most is
// real information - it simply no longer decides the status.
const status = rejected       ? 'REJECTED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' — ' + r.why),
    note: rejected
      ? 'quote refused by validation; nothing was written and nothing needed to be'
      : (dropped.length
          ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
            + (critical.length ? ' (' + critical.length + ' of them critical)' : '')
          : 'all ' + results.length + ' claimed steps verified'),
  },
} }];

// NEXUS - Resolve Tenant (finance calculator)
// ---------------------------------------------------------------------------
// finance_quotes is the table INV-001 makes the single source of every APR and
// instalment this business is allowed to show a customer. n8n writes it as
// service_role - BYPASSRLS, no auth.uid() - so a row without an explicit
// tenant_id is filed by the column default under whichever tenant holds
// is_unattributed_default. A second dealership's quote would then sit inside
// the first dealership's tenant, where its staff can read a rate that was
// quoted to somebody else's customer.
//
// ---- REWRITTEN 18 Sep 2026 (tenant-precedence wave) -----------------------
// REPLACES the 6 Sep resolver, which took the tenant_members row for the
// verified JWT user FIRST but, when that produced nothing, fell back to
// `Called as Tool`.tenant_id and then to `Webhook Trigger`.body.tenant_id.
// That last step was the defect: an authenticated user of dealership A could
// POST `tenant_id: <B>` and, on any execution where the membership lookup came
// back empty, have this workflow file the quote under B. The caller's value is
// never a source now. On the public door it is only ever a CLAIM, and a claim
// that disagrees with the membership row is refused.
//
// Two doors, two rules:
//   * public webhook -- `Webhook Trigger` -> `Verify JWT` ->
//     `Calculate Equity & Tier` -> `Tenant For JWT User` -> here. The ONLY
//     trusted answer is the tenant_members row for the Supabase user behind the
//     verified JWT. No row, or more than one row, means refuse; there is NO
//     fallback on this door, because a fallback is exactly how an unverifiable
//     caller acquires a dealership. This also subsumes the 6 Sep
//     anonymousWebhook case: an unauthenticated caller has no membership row,
//     so it refuses here rather than reaching sole_configured_tenant.
//   * internal hop -- `Called as Tool` -> `Calculate Equity & Tier` -> here.
//     `Verify JWT` never ran, which is how this node tells the doors apart.
//     The sibling workflow already resolved the dealership, so its UUID is
//     accepted; absent that, a single configured dealership is named
//     explicitly - stated rather than defaulted.
//
// Refusals carry the '[NEXUS-UNATTRIBUTED]' prefix at position 0, the contract
// with the NEXUS Error Handler (iYJkh1kztWxZXDbT): the failed execution is
// filed under the quarantine tenant instead of being appended to some real
// dealership's audit trail.
//
// This node CARRIES THE CALCULATION THROUGH UNCHANGED. It re-reads it from
// 'Calculate Equity & Tier' by name rather than from $input, because the HTTP
// node before it replaced the item with the tenant lookup's response. No figure
// is recomputed here, so INV-001's one-figure-one-derivation rule is untouched.
const NEXUS_BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // ALBA CARS
const NEXUS_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let nexusMap = {};
try { nexusMap = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { nexusMap = {}; }
if (!nexusMap || typeof nexusMap !== 'object' || !Object.keys(nexusMap).length) nexusMap = NEXUS_BUILTIN;
const nexusKeys = Object.keys(nexusMap);

// Which door? `$()` throws for a node that did not run in this execution.
// `Tenant For JWT User` is NOT usable for this test: it sits on both branches
// (Calculate Equity & Tier feeds it from the tool path too, where it queries
// the all-zero uuid). `Verify JWT` runs on the webhook branch and only there.
let viaWebhook = true;
try { $('Verify JWT').all(); } catch (e) { viaWebhook = false; }

// What the caller ASSERTED. Never authoritative; only ever cross-checked.
let claimed = '';
if (viaWebhook) {
  try {
    const wh = $('Webhook Trigger').first().json || {};
    claimed = String((wh.body && wh.body.tenant_id) || wh.tenant_id || '');
  } catch (e) { claimed = ''; }
} else {
  try {
    const tj = $('Called as Tool').first().json || {};
    claimed = String(tj.tenant_id || '');
  } catch (e) { claimed = ''; }
}

let tenant = null;
let source = 'unresolved';

if (viaWebhook) {
  let ids = [];
  try {
    ids = Array.from(new Set(
      $('Tenant For JWT User').all()
        .map((i) => (i && i.json ? i.json.tenant_id : null))
        .filter(Boolean)
        .map(String)
    ));
  } catch (e) { ids = []; }
  if (ids.length > 1) {
    throw new Error('[NEXUS-UNATTRIBUTED] Finance quote rejected: the authenticated user is a member of ' + ids.length + ' dealerships. This endpoint will not choose one on their behalf.');
  }
  if (ids.length === 0 || !NEXUS_UUID.test(ids[0])) {
    throw new Error('[NEXUS-UNATTRIBUTED] Finance quote rejected: the authenticated user has no tenant_members row. A dealership is never taken from the request body.');
  }
  if (claimed && claimed.toLowerCase() !== ids[0].toLowerCase()) {
    throw new Error('[NEXUS-UNATTRIBUTED] Finance quote rejected: caller asserted tenant_id ' + claimed + ' but is a member of ' + ids[0] + '. tenant_id is not a caller-selectable field.');
  }
  tenant = ids[0];
  source = 'jwt_tenant_member';
} else {
  if (NEXUS_UUID.test(claimed)) {
    tenant = claimed;
    source = 'internal_caller';
  } else if (nexusKeys.length === 1 && NEXUS_UUID.test(String(nexusMap[nexusKeys[0]] || ''))) {
    tenant = String(nexusMap[nexusKeys[0]]);
    source = 'sole_configured_tenant';
  } else {
    throw new Error('[NEXUS-UNATTRIBUTED] Finance quote rejected: the internal caller supplied no resolvable tenant_id and ' + nexusKeys.length + ' dealerships are configured. Refusing rather than filing this quote under a guess.');
  }
}

const calc = $('Calculate Equity & Tier').first().json || {};
return [{ json: Object.assign({}, calc, { tenant_id: tenant, tenant_source: source }) }];

// ============================================================================
// Finance Calc -- entry, input recovery, validation, quote
// ============================================================================
//
// -- EMI extension (31 Aug 2026) ---------------------------------------------
// This node could not compute an instalment at all. On 31 Aug a live customer
// asked "what would the monthly payment be over 60 months?" and the agent
// invented AED 11,200/month -- it had amortised the full AED 585,000, i.e.
// 100% financing, which no UAE bank offers. The true figure was ~7,800-9,200.
//
// Everything below the ORIGINAL banner is unchanged in behaviour; the EMI
// block is purely additive and every pre-existing output field keeps its name
// and its value. Rules applied:
//   * A 20% down-payment floor (80% LTV) is enforced. It was written here as
//     "CBUAE Regulation No. 29/2011"; that attribution is UNVERIFIED and is now
//     recorded as such in public.policy_rule, so the floor is enforced but is
//     no longer described to a customer as anyone's regulation. Banks
//     commercially cap USED cars at 70% LTV (30% down) and ALBA CARS sells used
//     cars, so 30% is what we ASSUME when the customer states nothing; a stated
//     20-30% is still quoted, but flagged as below what banks usually want.
//   * Maximum repayment period 60 months. Hard cap, never exceeded. Same
//     UNVERIFIED regulatory status as the floor above.
//   * Reducing-balance amortisation: P * r / (1 - (1+r)^-n), r = apr/100/12.
//     The BANDS APRs are already reducing-balance, so they feed this directly.
//   * Positive trade-in equity is real money and counts toward the down
//     payment; negative equity is NOT rolled into the loan here.
//
// The whole body is wrapped in try/catch: this node's contract is that every
// failure is a RETURNED item, never a thrown execution.
// ============================================================================
try {

//
// -- Entry-path resolution ---------------------------------------------------
// Webhook Trigger -> Verify JWT -> here   (public HTTP; auth enforced)
// Called as Tool  -> here                 (sub-workflow; already trusted)
//
// $('Webhook Trigger') THROWS when that node did not run in this execution --
// it does NOT return undefined, so `?.` and `||` cannot rescue it, and an
// Expression field cannot hold try/catch. That is why this lives in a Code node.
let webhookJson = null;
try {
  webhookJson = $('Webhook Trigger').first().json;
} catch (e) {
  // tool / sub-workflow path -- Webhook Trigger never executed.
}

let src;
let viaWebhook = false;
if (webhookJson) {
  viaWebhook = true;
  // 'Verify JWT' runs with onError = continueRegularOutput, so a rejected
  // token arrives here as data instead of failing the execution.
  const auth = $input.first().json || {};
  if (!auth.id) {
    return [{ json: {
      status: 'error',
      errors: ['Unauthorized. A valid Supabase session token is required in the Authorization header.'],
      calculatedAt: new Date().toISOString()
    } }];
  }
  src = webhookJson.body || webhookJson;
} else {
  src = $input.first().json || {};
}

// -- Degraded-mode envelope recovery (30 Aug 2026) ---------------------------
// n8n decides how a toolWorkflow presents itself to the model from ONE thing:
// whether the CALLER node's persisted `workflowInputs.schema` array is
// non-empty (WorkflowToolService.ts: `useSchema = (schema ?? []).length > 0`).
// It never inspects the sub-workflow at runtime. If that array is empty the
// tool degrades to a LangChain DynamicTool -- a single free-text parameter --
// and every argument the model produced arrives as ONE JSON string.
//
// This node is the last line of defence for that case. On 30 Aug exec 6668 the
// agent called this tool ELEVEN times in 147s, cycling field names and quoting
// styles, trying to guess a contract it could not satisfy; the customer got a
// canned apology. Recover the arguments rather than reject them.
//
// The wrapper key differs by layer: n8n re-wraps as { query: ... }, while the
// LangChain tool-call argument is logged as { input: ... }. Accept both.
// Both keys must ALSO be declared on the Called as Tool trigger, because a
// schema-declared trigger hard-filters every undeclared key
// (ExecuteWorkflowTrigger: pickBy(json, key => declaredKeys.has(key))).
function asObject(v) {
  if (v === null || v === undefined) return {};
  if (typeof v === 'object') return v;
  if (typeof v === 'string') {
    const s = v.trim();
    if (!s) return {};
    if (s[0] === '{' || s[0] === '[') {
      try { const p = JSON.parse(s); return (p && typeof p === 'object') ? p : {}; } catch (e) { return {}; }
    }
    // Bare scalar, e.g. the model sent just "600". Only a lone number is
    // unambiguous enough to interpret, and only as the credit score --
    // it is the one argument this tool always needs.
    if (/^\d{3}$/.test(s)) return { creditScore: Number(s) };
    return {};
  }
  return {};
}

const envelope = Object.assign({}, asObject(src.input), asObject(src.query));
const degraded = Object.keys(envelope).length > 0;

// A schema-declared trigger pre-seeds every declared field with null, so a
// field the caller did not supply is null here, not undefined. Treat both as
// absent and fall back to the envelope.
function pick(key) {
  const direct = src[key];
  if (direct !== undefined && direct !== null && direct !== '') return direct;
  return envelope[key];
}

// -- Inputs ------------------------------------------------------------------
const MIN_VEHICLE_VALUE_AED = 5000;

const rawVehicleIn = pick('vehicleValue');
const rawPayoffIn  = pick('loanPayoffAmount');
const rawVehicle = (rawVehicleIn === undefined || rawVehicleIn === null || rawVehicleIn === '')
  ? NaN : parseFloat(rawVehicleIn);
const rawPayoff = (rawPayoffIn === undefined || rawPayoffIn === null || rawPayoffIn === '')
  ? NaN : parseFloat(rawPayoffIn);
// Credit score is entered manually from the customer's AECB report -- real-time
// bureau lookups need a licensed financial-institution agreement in the UAE.
const creditScore = parseInt(pick('creditScore'), 10);

// -- EMI inputs (additive, all optional) -------------------------------------
// DEFAULT DOWN PAYMENT -- single point of change, change it here and nowhere else.
const DEFAULT_DOWN_PAYMENT_PCT = 30; // used-car norm (70% LTV) assumed when the customer states nothing

// Two different numbers, deliberately kept apart:
//   MIN_DOWN_PAYMENT_PCT  -- the HARD floor this desk quotes within. A stated
//     down payment below it is refused outright. It has long been ANNOTATED as
//     CBUAE Regulation No. 29/2011, but that attribution has never been checked
//     against the instrument by anyone on this project: it is registered in
//     public.policy_rule as AE/FINANCE/MIN_DOWN_PAYMENT_PCT, DRAFT /
//     NOT_VERIFIED, source "A constant in this codebase -- NOT a central bank".
//     Enforce it; do not tell a customer whose rule it is.
//   DEFAULT_DOWN_PAYMENT_PCT -- what we ASSUME when the customer stated nothing.
//     UAE banks commercially cap USED cars at 70% LTV and ALBA CARS sells used
//     cars, so the assumption is 30%. A stated 20-30% is still quoted, but
//     flagged as below what a bank will usually want on a used car.
const MIN_DOWN_PAYMENT_PCT = 20;                           // desk floor, ENFORCED. Regulatory status UNVERIFIED -- policy_rule AE/FINANCE/MIN_DOWN_PAYMENT_PCT
const MAX_LTV_PCT       = 100 - MIN_DOWN_PAYMENT_PCT;      // 80% -- the floor enforced
const USED_CAR_LTV_PCT  = 100 - DEFAULT_DOWN_PAYMENT_PCT;  // 70% -- the commercial norm
const DEFAULT_TENURE_MONTHS = 60;
const MAX_TENURE_MONTHS = 60;   // desk cap, ENFORCED. Never exceed. Regulatory status
                                // UNVERIFIED -- policy_rule AE/FINANCE/MAX_TENURE_MONTHS.
                                // NOTE: this rule also exists in TWO places this workflow
                                // does not own -- a CHECK constraint on finance_quotes
                                // (finance_quotes_tenure_months_check) and the browser
                                // constant MAX_TENURE_MONTHS_CBUAE in
                                // apps/executive-dashboard/screens/finance.js. Three copies,
                                // one unverified figure.
const MIN_TENURE_MONTHS = 12;

function num(v) {
  if (v === undefined || v === null || v === '') return NaN;
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : NaN;
}

// vehiclePrice is the car being BOUGHT. vehicleValue (above) is the TRADE-IN.
// They are different numbers and conflating them is what produced the AED
// 11,200 figure, so they are kept strictly separate.
const rawVehiclePrice   = num(pick('vehiclePrice'));
const rawDownPayment    = num(pick('downPayment'));
const rawDownPaymentPct = num(pick('downPaymentPct'));
const rawTenureMonths   = num(pick('tenureMonths'));

// A customer with NO trade-in still deserves a rate. vehicleValue used to be
// unconditionally mandatory, so a cash-in-hand buyer asking "what rate do I
// get?" could never be answered -- the tool rejected the call and the agent
// asked for a trade-in value the customer did not have.
const hasTradeIn = Number.isFinite(rawVehicle) && rawVehicle >= MIN_VEHICLE_VALUE_AED;
const vehicleValue = hasTradeIn ? rawVehicle : 0;
const loanPayoffAmount = Number.isFinite(rawPayoff) && rawPayoff >= 0 ? rawPayoff : 0;

// Attribution. A finance figure carrying a lender disclaimer must be traceable
// to a customer. SECURITY: prefer the caller-injected value. The envelope is
// model-controlled, so it is only a fallback for degraded mode, and when it is
// used the quote is flagged so the Finance Desk can see the identity was not
// established by the workflow.
const callerEmail = (src.lead_email || '').toString().trim();
const envEmail = (envelope.lead_email || envelope.email || '').toString().trim();
const leadEmail = callerEmail || envEmail || null;
const emailFromModel = !callerEmail && !!envEmail;
const leadName = (src.lead_name || envelope.lead_name || envelope.name || null);
const quotedBy = (src.quoted_by || envelope.quoted_by || envelope.rep || null);

// -- Validation --------------------------------------------------------------
// Error payloads are written FOR A LANGUAGE MODEL, not for a log file. A bare
// list of complaints made the agent retry the same call eleven times. Every
// rejection now leads with an imperative instruction telling the agent exactly
// what to do next, and never to repeat the same call.
const problems = [];
if (Number.isFinite(rawVehicle) && rawVehicle > 0 && rawVehicle < MIN_VEHICLE_VALUE_AED) {
  problems.push('vehicleValue was ' + rawVehicle + ', which is too small to be a real vehicle. Omit vehicleValue entirely if the customer has no trade-in.');
}
if (Number.isFinite(rawPayoff) && rawPayoff < 0) {
  problems.push('loanPayoffAmount cannot be negative. Use 0 when there is no outstanding loan.');
}
if (!hasTradeIn && Number.isFinite(rawPayoff) && rawPayoff > 0) {
  problems.push('loanPayoffAmount was supplied without a vehicleValue. Send both, or neither.');
}
if (!Number.isFinite(creditScore) || creditScore < 300 || creditScore > 900) {
  problems.push('creditScore is missing or outside 300-900. It is the only argument this tool always needs.');
}
if (!leadEmail) {
  problems.push('lead_email did not reach this tool. This is a WORKFLOW WIRING FAULT, not something the customer can fix.');
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(leadEmail)) {
  problems.push('lead_email "' + leadEmail + '" is not a valid email address.');
}

if (problems.length) {
  const emailIsTheOnlyProblem = problems.length === 1 && problems[0].indexOf('WORKFLOW WIRING FAULT') !== -1;
  return [{ json: {
    status: 'input_error',
    // The model reads this first. Keep it imperative and unambiguous.
    instruction: emailIsTheOnlyProblem
      ? 'STOP. Do not call finance_calculator again in this turn -- retrying cannot fix this, the fault is in the workflow wiring and not in your arguments. Tell the customer, in their own language, that you are getting their indicative rate confirmed by a colleague and will come straight back with it. Do not mention tools, systems or errors, and do not ask them for an email address.'
      : 'Fix the arguments listed in `problems` and call finance_calculator exactly ONCE more. Never repeat a call with arguments you have already tried. If you cannot fix them from the conversation, stop calling tools and ask the customer, in plain language, for the single missing detail.',
    problems: problems,
    expected: {
      creditScore: 'number, 300-900, REQUIRED. The customer AECB score.',
      vehicleValue: 'number, AED, OPTIONAL. Trade-in market value. Omit if no trade-in.',
      loanPayoffAmount: 'number, AED, OPTIONAL. Outstanding loan on the trade-in. Omit if no trade-in.',
      lead_email: 'Supplied automatically by the workflow. NEVER ask the customer for it.'
    },
    example_valid_call: { creditScore: 720, vehicleValue: 85000, loanPayoffAmount: 20000 },
    example_valid_call_no_trade_in: { creditScore: 720 },
    lead_email: leadEmail,
    lead_name: leadName,
    _degraded: degraded,
    calculatedAt: new Date().toISOString()
  } }];
}

// -- Rate bands --------------------------------------------------------------
// Rewritten 30 Aug 2026. The previous table quoted a SINGLE point APR per band
// on US FICO cut-offs (720/680/620, "Prime Plus"/"Subprime"), and its weakest
// band quoted 12.5% -- above Emirates NBD's published ceiling of 9.00%
// reducing / 9.65% APR. Three things were wrong with that and all three
// mattered, because these numbers are read out to real customers on WhatsApp:
//
//   1. UAE banks advertise a FLAT rate; the true cost is the reducing-balance
//      rate, ~1.87x the flat rate over 60 months. An unlabelled number is read
//      as flat and therefore understates the cost by roughly half. This was
//      justified here by "CBUAE Consumer Protection Standard 2.3.1.13", which
//      is ITSELF an UNVERIFIED citation and is not registered in policy_rule.
//      It stays only as a comment: labelling the APR is the conservative
//      behaviour whether or not the standard says so, and no customer-facing
//      string repeats the citation. Do not promote it into one.
//   2. Band cut-offs now follow ADCB's published AECB bands -- the only band
//      set published by an actual UAE lender. AECB itself publishes none.
//   3. No single point rate is quoted. Every UAE lender publishes a range and
//      states the bank sets the final rate on approval; a dealer asserting one
//      exact figure is asserting something it does not control.
//
// Basis: used car, 60-month term, salary transfer. Ranges are anchored to the
// observed used-car market at the strong end and capped at Emirates NBD's
// published 9.00% reducing / 9.65% APR ceiling at the weak end.
// Without salary transfer, add roughly 1.4pp -- surfaced as a caveat.
const BANDS = [
  { min: 746, band: 'Excellent', aprLow: 5.3, aprHigh: 6.7,  flatLow: 2.50, flatHigh: 3.20 },
  { min: 711, band: 'Very good', aprLow: 5.9, aprHigh: 7.5,  flatLow: 2.75, flatHigh: 3.65 },
  { min: 651, band: 'Good',      aprLow: 6.7, aprHigh: 8.7,  flatLow: 3.20, flatHigh: 4.35 },
  { min: 541, band: 'Fair',      aprLow: 8.2, aprHigh: 9.65, flatLow: 4.05, flatHigh: 4.90 }
];
const hit = BANDS.find(b => creditScore >= b.min) || null;

// -- DISCLAIMER (rewritten 3 Sep 2026) ---------------------------------------
// This string is read out to customers on WhatsApp. It used to end
//   "Min 20% down payment, max 60 months (UAE Central Bank rules)."
// which put a REGULATOR'S NAME behind two numbers that came from constants
// typed into apps/executive-dashboard/screens/finance.js with no source, no
// effective date and no verifier. Both are registered in public.policy_rule as
// AE/FINANCE/MIN_DOWN_PAYMENT_PCT and AE/FINANCE/MAX_TENURE_MONTHS, both
// DRAFT / NOT_VERIFIED, and public.v_policy_authoritative returns ZERO rows --
// so there is nothing authoritative to quote. policy_citation() for either of
// them does not return a hedge, it RAISES: "There is no verified source ... so
// no regulatory claim may be made about it. Get one, or say nothing."
//
// So we say nothing about any regulator. What is left is not a claim about UAE
// law or about any bank's credit policy -- it is a statement about THIS QUOTE:
// these are the limits the calculator computed within, provable from the code
// and from the finance_quotes row this run writes. That is the only version of
// the sentence the dealership can defend to a customer who asks.
//
// The percentages are interpolated from the enforced constants rather than
// retyped, so the sentence cannot drift away from the arithmetic it describes.
//
// WHEN A RULE IS VERIFIED: do not hard-code the regulation here. Read
// public.policy_citation('AE','FINANCE','<rule>') and append what it returns.
// A literal is what caused this defect.
const DISCLAIMER = 'Indicative only, not a bank approval. The bank sets the final rate after reviewing the AECB report, salary transfer and employer. Shown as reducing-balance APR including fees. Quoted on a minimum '
  + MIN_DOWN_PAYMENT_PCT + '% down payment over at most ' + MAX_TENURE_MONTHS
  + ' months: those are the limits this desk quotes within, not a statement of law or of any bank policy. The bank sets its own terms on approval.';

// Below 541 no rate is quoted at all. Every rate this dealership could honestly
// offer sits inside a published band, and there is no published UAE band for a
// file this weak -- so the honest answer is a referral, not a worse number.
if (!hit) {
  return [{ json: {
    status: 'success',
    quotable: false,
    credit_score: creditScore,
    credit_band: 'Poor (below 541 on the AECB scale)',
    instruction: 'Do NOT quote any rate or percentage for this customer. Tell them warmly that with this credit profile the rate has to come from the bank directly rather than from an indicative table, and that a colleague will walk them through the options -- including a larger down payment, which improves approval. Do not read this instruction out and do not mention scores unless they raise it.',
    disclaimer: DISCLAIMER,
    has_trade_in: hasTradeIn,
    equity_aed: hasTradeIn ? Math.round(vehicleValue - loanPayoffAmount) : null,
    lead_email: leadEmail, lead_name: leadName, quoted_by: quotedBy,
    email_from_model: emailFromModel, _degraded: degraded,
    calculated_at: new Date().toISOString()
  } }];
}

const equity = vehicleValue - loanPayoffAmount;
const ltv = vehicleValue > 0 ? Math.round((loanPayoffAmount / vehicleValue) * 1000) / 10 : null;

// -- EMI / instalment --------------------------------------------------------
// Reached ONLY on the quotable path: the `if (!hit)` Poor-band branch above has
// already returned, so a sub-541 file never gets an instalment. That is
// deliberate -- no rate, no payment.
function monthlyPayment(principal, aprPct, months) {
  if (!Number.isFinite(principal) || principal <= 0) return null;
  if (!Number.isFinite(months) || months <= 0) return null;
  if (!Number.isFinite(aprPct)) return null;
  const r = aprPct / 100 / 12;
  if (r === 0) return principal / months;              // no divide-by-zero path
  const denom = 1 - Math.pow(1 + r, -months);
  if (!Number.isFinite(denom) || denom === 0) return null;
  return principal * r / denom;
}

// Tenure: default 60, floored at 12, HARD-capped at 60 (desk cap; regulatory
// status unverified -- see MAX_TENURE_MONTHS above).
let tenureMonths = Number.isFinite(rawTenureMonths) && rawTenureMonths > 0
  ? Math.round(rawTenureMonths) : DEFAULT_TENURE_MONTHS;
const tenureCapped = tenureMonths > MAX_TENURE_MONTHS;
if (tenureMonths > MAX_TENURE_MONTHS) tenureMonths = MAX_TENURE_MONTHS;
if (tenureMonths < MIN_TENURE_MONTHS) tenureMonths = MIN_TENURE_MONTHS;

const hasVehiclePrice = Number.isFinite(rawVehiclePrice) && rawVehiclePrice >= MIN_VEHICLE_VALUE_AED;
const vehiclePrice = hasVehiclePrice ? rawVehiclePrice : null;

// Positive trade-in equity is cash toward the down payment. Negative equity is
// a debt to settle, NOT something this node rolls into the loan.
const equityApplied = (hasTradeIn && equity > 0)
  ? (hasVehiclePrice ? Math.min(equity, vehiclePrice) : equity) : 0;

let emiAvailable = false;
let emiReason = null;
let minDownPayment = null;
let downPaymentCash = null;
let downPaymentTotal = null;
let downPaymentPct = null;
let downPaymentAssumed = false;
let downPaymentShortfall = null;
let belowUsedCarNorm = false;
let normDownPayment = null;
let financed = null;
let monthlyLow = null, monthlyHigh = null;
let totalCreditLow = null, totalCreditHigh = null;
let monthlyRange = null;
let emiInstruction = null;

if (!hasVehiclePrice) {
  emiReason = 'No vehiclePrice was supplied, so no monthly payment can be calculated. '
    + 'Do NOT invent, estimate or guess a monthly figure. Ask the customer which vehicle '
    + '(or its price) and call finance_calculator once more with vehiclePrice.';
} else {
  minDownPayment  = Math.round(vehiclePrice * (MIN_DOWN_PAYMENT_PCT / 100));
  normDownPayment = Math.round(vehiclePrice * (DEFAULT_DOWN_PAYMENT_PCT / 100));

  // A stated down payment is CASH from the customer; trade-in equity is on top.
  let statedCash = NaN;
  if (Number.isFinite(rawDownPayment) && rawDownPayment >= 0) {
    statedCash = rawDownPayment;
  } else if (Number.isFinite(rawDownPaymentPct) && rawDownPaymentPct >= 0 && rawDownPaymentPct <= 100) {
    statedCash = vehiclePrice * (rawDownPaymentPct / 100);
  }

  if (Number.isFinite(statedCash)) {
    downPaymentCash = statedCash;
    downPaymentTotal = statedCash + equityApplied;
  } else {
    // Nothing stated -> apply the used-car norm, and say so. Trade-in equity
    // counts toward that floor rather than being added on top of it.
    downPaymentAssumed = true;
    downPaymentTotal = Math.max(normDownPayment, equityApplied);
    downPaymentCash = downPaymentTotal - equityApplied;
  }

  if (downPaymentTotal + 0.5 < minDownPayment) {
    // Never silently raise the customer's number. Name the gap instead.
    downPaymentShortfall = Math.round(minDownPayment - downPaymentTotal);
    // 3 Sep 2026: this text is relayed to the customer by the agent, so the
    // words "legal minimum" and "the UAE Central Bank caps" were a regulatory
    // claim resting on an unverified constant (policy_rule
    // AE/FINANCE/MIN_DOWN_PAYMENT_PCT, DRAFT / NOT_VERIFIED). The floor is
    // still enforced exactly as before -- it is just no longer attributed to
    // anyone who has not been checked.
    emiReason = 'The stated down payment of AED ' + Math.round(downPaymentTotal)
      + ' is below the minimum this desk quotes on, AED ' + minDownPayment + ' ('
      + MIN_DOWN_PAYMENT_PCT + '% of AED ' + Math.round(vehiclePrice)
      + '). Do NOT describe this minimum as a legal or regulatory requirement -- there is no verified source for that. '
      + 'Shortfall AED ' + downPaymentShortfall + '. Tell the customer that AED '
      + minDownPayment + ' is the minimum this quote can be built on -- do not quote a monthly payment and do '
      + 'not pretend the smaller amount works. On a used car most banks will actually want '
      + DEFAULT_DOWN_PAYMENT_PCT + '% (AED ' + normDownPayment + ').';
  } else if (vehiclePrice - downPaymentTotal <= 0) {
    financed = 0;
    emiReason = 'The down payment and trade-in equity cover the full price, so no '
      + 'finance is needed. Do not quote a monthly payment.';
  } else {
    financed = vehiclePrice - downPaymentTotal;
    belowUsedCarNorm = downPaymentTotal + 0.5 < normDownPayment;
    const pLow  = monthlyPayment(financed, hit.aprLow,  tenureMonths);
    const pHigh = monthlyPayment(financed, hit.aprHigh, tenureMonths);
    if (pLow === null || pHigh === null) {
      emiReason = 'The instalment could not be computed from the supplied figures. '
        + 'Do not invent a monthly payment.';
    } else {
      emiAvailable = true;
      monthlyLow  = Math.round(pLow);
      monthlyHigh = Math.round(pHigh);
      monthlyRange = monthlyLow + ' - ' + monthlyHigh;
      totalCreditLow  = Math.round(pLow  * tenureMonths - financed);
      totalCreditHigh = Math.round(pHigh * tenureMonths - financed);
      emiInstruction = 'Quote the monthly payment as a RANGE (AED ' + monthlyRange
        + ' over ' + tenureMonths + ' months), never a single figure, and always state the '
        + 'down payment you assumed. '
        + (downPaymentAssumed
            ? 'The customer did NOT state a down payment -- you assumed '
              + DEFAULT_DOWN_PAYMENT_PCT + '% (AED ' + Math.round(downPaymentTotal)
              + '). Say so explicitly.'
            : 'This uses the down payment the customer stated (AED '
              + Math.round(downPaymentTotal) + ').')
        + (equityApplied > 0
            ? ' AED ' + Math.round(equityApplied) + ' of that comes from their trade-in equity.'
            : '')
        + (belowUsedCarNorm
            ? ' WARNING: that is below the ' + DEFAULT_DOWN_PAYMENT_PCT + '% most UAE banks want on a '
              + 'USED car (' + USED_CAR_LTV_PCT + '% LTV). This desk will still quote down to '
              + MIN_DOWN_PAYMENT_PCT + '%, but the bank may require AED ' + normDownPayment
              + '. Say so, and do NOT tell the customer whether any regulator permits it -- we have no verified source for that.'
            : '')
        + ((hasTradeIn && equity < 0)
            ? ' Their trade-in is in negative equity (AED ' + Math.abs(Math.round(equity))
              + ' owing above its value); that must be settled separately and is NOT in this payment.'
            : '')
        + ' Never present it as a bank approval.';
    }
  }
  if (!emiAvailable && downPaymentTotal !== null) {
    downPaymentPct = Math.round((downPaymentTotal / vehiclePrice) * 1000) / 10;
  }
}
if (emiAvailable) {
  downPaymentPct = Math.round((downPaymentTotal / vehiclePrice) * 1000) / 10;
}

return [{
  json: {
    status: 'success',
    quotable: true,
    credit_score: creditScore,
    credit_band: hit.band,
    // Always a range, always labelled. Never emit a bare number downstream.
    indicative_apr_range_pct: hit.aprLow + ' - ' + hit.aprHigh,
    indicative_apr_low_pct: hit.aprLow,
    indicative_apr_high_pct: hit.aprHigh,
    rate_basis: 'reducing-balance APR, inclusive of fees',
    equivalent_flat_rate_range_pct: hit.flatLow + ' - ' + hit.flatHigh,
    assumes: 'used car, 60-month term, salary transfer to the lending bank',
    without_salary_transfer_note: 'Without salary transfer add roughly 1.4 percentage points.',
    instruction: 'Quote the RANGE, never a single figure, and always say it is reducing-balance APR. Include the disclaimer. Do not convert to a monthly payment unless the customer asks and you know the vehicle price and down payment. Never present the flat-rate equivalent on its own.',
    disclaimer: DISCLAIMER,
    has_trade_in: hasTradeIn,
    equity_aed: hasTradeIn ? Math.round(equity) : null,
    equity_status: hasTradeIn ? (equity >= 0 ? 'Positive' : 'Negative') : 'No trade-in',
    loan_to_value_pct: ltv,
    vehicle_value_aed: hasTradeIn ? Math.round(vehicleValue) : null,
    loan_payoff_aed: hasTradeIn ? Math.round(loanPayoffAmount) : null,
    lead_email: leadEmail,
    lead_name: leadName,
    quoted_by: quotedBy,
    email_from_model: emailFromModel,
    _degraded: degraded,
    _via_webhook: viaWebhook,

    // -- EMI block (additive, 31 Aug 2026). Nothing above this line changed. --
    emi_available: emiAvailable,
    emi_unavailable_reason: emiReason,
    emi_instruction: emiInstruction,
    vehicle_price_aed: hasVehiclePrice ? Math.round(vehiclePrice) : null,
    max_ltv_pct: MAX_LTV_PCT,
    min_down_payment_aed: minDownPayment,
    down_payment_aed: downPaymentTotal === null ? null : Math.round(downPaymentTotal),
    down_payment_cash_aed: downPaymentCash === null ? null : Math.round(downPaymentCash),
    down_payment_pct: downPaymentPct,
    down_payment_assumed: downPaymentAssumed,
    down_payment_shortfall_aed: downPaymentShortfall,
    down_payment_below_used_car_norm: belowUsedCarNorm,
    trade_in_equity_applied_aed: Math.round(equityApplied),
    financed_aed: financed === null ? null : Math.round(financed),
    tenure_months: tenureMonths,
    tenure_capped: tenureCapped,
    monthly_payment_low_aed: monthlyLow,
    monthly_payment_high_aed: monthlyHigh,
    monthly_payment_range_aed: monthlyRange,
    total_cost_of_credit_low_aed: totalCreditLow,
    total_cost_of_credit_high_aed: totalCreditHigh,

    calculated_at: new Date().toISOString()
  }
}];

} catch (err) {
  // The node's contract: every failure is a RETURNED item, never a thrown
  // execution. Anything unexpected -- malformed $input, a missing helper, a
  // numeric edge case -- lands here instead of failing the whole workflow.
  return [{ json: {
    status: 'error',
    errors: ['finance_calculator failed internally: ' + ((err && err.message) ? err.message : String(err))],
    instruction: 'STOP. Do not call finance_calculator again in this turn. Tell the customer, in their own language, that you are having their figures confirmed by a colleague and will come straight back. Do not mention tools or errors, and NEVER invent a rate or a monthly payment.',
    calculatedAt: new Date().toISOString()
  } }];
}

// Re-emit the calculation. 'Log Quote' returns an empty body
// (Prefer: return=minimal), so without this the webhook would answer with
// nothing. Also keeps the sub-workflow caller contract intact.
return $('Calculate Equity & Tier').all();

// Delivery Report - the last workflow still asserting a write it never checked.
//
// `Log Quote` swallows its own failure (onError: continueRegularOutput) and
// `Audit Log` decided SUCCESS purely from whether the MATHS succeeded, never
// from whether the `finance_quotes` row landed. So a dropped insert produced a
// green audit row and an empty Finance Desk.
//
// Two inbound paths meet here: the valid-quote path through `Log Quote`, and
// the rejected path straight from `Quote Valid?`. `$('Log Quote')` THROWS on
// the second one -- a rejection is not a drop, so it is not claimed there.
const calc = $('Calculate Equity & Tier').first().json;
const rejected = calc.status !== 'success';

const CLAIMED = rejected ? [] : [
  { node: 'Log Quote', what: 'finance_quotes row (the quote the Finance Desk reads)', critical: true },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 200) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);
const dropped = results.filter(r => !r.ok);
const critical = dropped.filter(r => r.critical);

// A rejection is a correct outcome, not a failure to deliver. It keeps its own
// status so the Finance Desk can still tell "we refused to quote" apart from
// "we quoted and lost it".
//
// -- 01 Sep 2026 - WHY THERE IS NO 'FAILED' RUNG ANY MORE ---------------------
// This node wrote FAILED whenever a dropped claim was tiered critical. 'Log
// Quote' is the ONLY claim and it was tiered critical, so the PARTIAL rung was
// unreachable and every lost finance_quotes row was filed as a failure. Five
// live rows read "Quote issued | 1 of 1 claimed steps did not land" under status
// FAILED. Read that sentence: the customer HAD the quote, only the record was
// lost. That is a partial delivery, and nexus_outcome_class() in Postgres has
// been carrying a correction rule to say so on this workflow's behalf. This
// change is what lets that rule be deleted.
//
// FAILED has exactly one owner: nexus_error_handler, the errorWorkflow set on
// this workflow, which writes it from an Error Trigger when an execution STOPS.
// This node only runs on an execution that did NOT stop, so it is structurally
// not entitled to claim the work could not complete. The worst it can honestly
// report is that some of the work did not land.
//
// `critical` is still computed and still reported - which claims matter most is
// real information - it simply no longer decides the status.
const status = rejected       ? 'REJECTED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' — ' + r.why),
    note: rejected
      ? 'quote refused by validation; nothing was written and nothing needed to be'
      : (dropped.length
          ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
            + (critical.length ? ' (' + critical.length + ' of them critical)' : '')
          : 'all ' + results.length + ' claimed steps verified'),
  },
} }];

// NEXUS - Resolve Tenant (finance calculator)
// ---------------------------------------------------------------------------
// finance_quotes is the table INV-001 makes the single source of every APR and
// instalment this business is allowed to show a customer. n8n writes it as
// service_role - BYPASSRLS, no auth.uid() - so a row without an explicit
// tenant_id is filed by the column default under whichever tenant holds
// is_unattributed_default. A second dealership's quote would then sit inside
// the first dealership's tenant, where its staff can read a rate that was
// quoted to somebody else's customer.
//
// SIGNALS, in order, none of them a default:
//   1. the Supabase user behind the VERIFIED JWT, mapped through
//      tenant_members by the node before this one (dashboard calculator);
//   2. a tenant the trusted caller passed in (sub-workflow / tool path);
//   3. a tenant on the webhook body.
// If none answers and exactly one dealership is configured, that one is named
// explicitly - today's behaviour, stated rather than defaulted. Two or more and
// the value is null, and the write omits the column rather than assert an owner.
//
// 6 Sep 2026 -- THE UNAUTHENTICATED CASE, which defeated all of the above.
// 'Calculate Equity & Tier' refuses an unauthenticated webhook caller by
// RETURNING an error item, not by throwing, so the item kept flowing and
// reached the sole_configured_tenant fallback below. The fallback then named
// ALBA CARS, and 'Audit Log' -- which correctly omits tenant_id whenever this
// node returns null -- was handed a real dealership and stamped an anonymous
// stranger's REJECTED row into that dealership's audit trail. Measured on
// 6 Sep 2026: eight of nine public endpoints did this; this was the one that
// did it through its own writer rather than through the shared error handler.
//
// The fallback exists for the case where NEXUS knows who is asking but has no
// per-caller signal. It must not fire when NEXUS knows the caller is nobody.
// So: if this execution came in over the public webhook and 'Verify JWT'
// produced no user, there is no dealership, full stop. audit_log's own DEFAULT
// nexus_default_tenant_id() then retains the row under the quarantine tenant --
// visible to nexus_quarantine_census(), unreadable by any dealership.
//
// This node CARRIES THE CALCULATION THROUGH UNCHANGED. It re-reads it from
// 'Calculate Equity & Tier' by name rather than from $input, because the HTTP
// node before it replaced the item with the tenant lookup's response. No figure
// is recomputed here, so INV-001's one-figure-one-derivation rule is untouched.
const BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // ALBA CARS
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let map = {};
try { map = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { map = {}; }
if (!map || typeof map !== 'object' || !Object.keys(map).length) map = BUILTIN;
const keys = Object.keys(map);

// Did this execution arrive over the PUBLIC webhook, and if so was the caller
// authenticated? $('Webhook Trigger') and $('Verify JWT') THROW when the node
// did not run in this execution, so both lookups are wrapped.
let viaWebhook = false;
try { $('Webhook Trigger').first(); viaWebhook = true; } catch (e) { viaWebhook = false; }
let authenticated = false;
if (viaWebhook) {
  try { authenticated = !!(($('Verify JWT').first().json || {}).id); } catch (e) { authenticated = false; }
}
const anonymousWebhook = viaWebhook && !authenticated;

let tenant = '';
let source = '';

try {
  const row = $input.all().map(i => i.json).find(x => x && x.tenant_id);
  if (row) { tenant = String(row.tenant_id); source = 'jwt_tenant_member'; }
} catch (e) { /* no lookup result */ }

if (!UUID.test(tenant)) {
  try {
    const j = $('Called as Tool').first().json || {};
    tenant = String(j.tenant_id || '');
    if (UUID.test(tenant)) source = 'caller';
  } catch (e) { /* webhook path */ }
}

if (!UUID.test(tenant)) {
  try {
    const b = ($('Webhook Trigger').first().json || {}).body || {};
    tenant = String(b.tenant_id || '');
    if (UUID.test(tenant)) source = 'webhook_body';
  } catch (e) { /* tool path */ }
}

// An unauthenticated caller does not get the sole-dealership fallback. A body
// field cannot rescue it either -- clear anything the caller named, because on
// this branch the only signal is one the caller controls.
if (anonymousWebhook) {
  tenant = null;
  source = 'unauthenticated';
} else {
  if (!UUID.test(tenant) && keys.length === 1) {
    tenant = String(map[keys[0]] || '');
    source = 'sole_configured_tenant';
  }
  if (!UUID.test(tenant)) { tenant = null; source = 'unresolved'; }
}

const calc = $('Calculate Equity & Tier').first().json || {};
return [{ json: Object.assign({}, calc, { tenant_id: tenant, tenant_source: source }) }];
